var pad = function (n) { return (n < 10 ? '0' : '') + n; };

var H = { HOOK_CHARS: HOOK_CHARS, BODY_MIN: BODY_MIN, BODY_MAX: BODY_MAX, BODY_ABSOLUTE_MIN: BODY_ABSOLUTE_MIN, BODY_HARD_MAX: BODY_HARD_MAX, HASHTAG_MAX: HASHTAG_MAX, LINK_IN_BODY_ALLOWED: LINK_IN_BODY_ALLOWED, POST_WINDOWS: POST_WINDOWS, MAX_POSTS_PER_DAY: MAX_POSTS_PER_DAY, MAX_POSTS_PER_WEEK: MAX_POSTS_PER_WEEK, MIN_POSTS_PER_WEEK: MIN_POSTS_PER_WEEK, MAX_PILLAR_SHARE: MAX_PILLAR_SHARE, FORMULA_COOLDOWN_DAYS: FORMULA_COOLDOWN_DAYS, GOALS: GOALS, hookOf: hookOf, charCount: charCount, nextSlot: nextSlot, atLocalTime: atLocalTime, localParts: localParts };

