var voiceArray = function (v) {
  if (v == null) return [];
  if (Array.isArray(v)) return v;
  if (typeof v === 'string') {
    try { var parsed = JSON.parse(v); return Array.isArray(parsed) ? parsed : [v]; }
    catch (e) { return [v]; }
  }
  return [];
};

