    //   supported    the claim's numbers are all found in one source
    //   needs_check  a partial match, or a claim with names but no numbers
    //   unsupported  the claim carries numbers and none of them appear anywhere
    var verdict, article_id = null, source_url = null, quote = null;
    if (best && wantNums.length && intersect(wantNums, best.numbers).length === wantNums.length) {
      verdict = 'supported';
      article_id = best.article_id;
      source_url = best.url;
      quote = sentenceCarrying(best.sentences, wantNums, wantNames);
    } else if (best && bestScore > 0) {
      verdict = 'needs_check';
      article_id = best.article_id;
      source_url = best.url;
      quote = sentenceCarrying(best.sentences, wantNums, wantNames);
    } else if (wantNums.length) {
      verdict = 'unsupported';
    } else {
      // No numbers to check and nothing matched: not a factual claim after all,
      // or one phrased without the figure. Flag for a human rather than pass it.
      verdict = 'needs_check';
    }

    return {
      claim: claim,
      article_id: article_id,
      source_url: source_url,
      source_quote: quote,
      verdict: verdict,
    };
  });
};

/** The source sentence that carries the most of the claim's tokens. */
var sentenceCarrying = function (sentences, nums, names) {
  var best = null;
  var bestScore = 0;
  (sentences || []).forEach(function (s) {
    var score = intersect(nums, numbersIn(s)).length * 3 + intersect(names, namesIn(s)).length;
    if (score > bestScore) { bestScore = score; best = s; }
  });
  return best ? best.trim().slice(0, 400) : null;
};

// Numbers that carry meaning: keep the digits and a trailing % or the leading $,
// drop ordinary years so "2026" in two places is not a false match on its own.
var numbersIn = function (text) {
  var out = {};
  var re = /\$?\d[\d,]*(?:\.\d+)?\s?(?:%|per ?cent|percent|kw|mw|gw|kwh|mwh|million|billion|m|bn|k)?/gi;
  var m;
  while ((m = re.exec(String(text || ''))) !== null) {
    var tok = m[0].toLowerCase().replace(/[, ]/g, '');
    // Drop a bare four-digit year; keep it if it has a unit or symbol attached.
    if (/^\d{4}$/.test(tok) && Number(tok) > 1990 && Number(tok) < 2100) continue;
    if (/\d/.test(tok)) out[tok] = true;
  }
  return Object.keys(out);
};

// Multi-word capitalised names: schemes, standards, agencies, places. Single
// capitalised words are too noisy (every sentence start), so require two.
var namesIn = function (text) {
  var out = {};
  var re = /\b([A-Z][A-Za-z]+(?:\s+(?:of|the|and|for)?\s*[A-Z][A-Za-z]+)+)\b/g;
  var m;
  while ((m = re.exec(String(text || ''))) !== null) {
    var name = m[1].replace(/\s+/g, ' ').trim().toLowerCase();
    if (name.length > 5) out[name] = true;
  }
  // Also capture well-known single-token acronyms that matter here.
  (String(text || '').match(/\b(NABERS|GEMS|VEU|CBD|NCC|AEMO|AER|CEC|PV)\b/g) || [])
    .forEach(function (a) { out[a.toLowerCase()] = true; });
  return Object.keys(out);
};

var intersect = function (a, b) {
  var set = {};
  (b || []).forEach(function (x) { set[x] = true; });
  return (a || []).filter(function (x) { return set[x]; });
};

var splitSentences = function (text) {
  return String(text || '').split(/(?<=[.!?])\s+|\n+/).map(function (s) { return s.trim(); }).filter(Boolean);
};

var dedupe = function (arr) {
  var seen = {};
  return (arr || []).filter(function (x) {
    var k = String(x).toLowerCase().replace(/\s+/g, ' ').trim();
    if (seen[k]) return false;
    seen[k] = true;
    return true;
  });
};



/**
 * Where an approved post goes, and how.
 *
 * Adapted from sergebulaev/linkedin-skills (MIT), lib/backend_selector.py.
 *
 * Three backends, highest privilege first:
 *
 *   linkedin  LinkedIn's official API against the BEXT page. Real auto-post.
 *             Needs a developer app and a Community Management API review, so it
 *             is off until the client has been through that, weeks out.
 *   publora   the Publora REST API. Auto-post in two minutes of setup, free tier
 *             15 posts a month. Adds a third party that holds the LinkedIn token.
 *   manual    the default. Produces the finished text and hands it to a human to
 *             paste. Nothing third-party holds a credential, and it ships this
 *             week.
 *
 * The brief asks for manual publishing at launch anyway ("approve and manually
 * publish"), so `manual` is not a fallback here, it is the intended path. The
 * other two exist so that turning on auto-post later is one environment variable
 * and changes nothing upstream of the approval.
 *
 * This module decides the route and shapes the payload. It does not itself make
 * the HTTP call: the n8n node does, so the request shows up in the execution log
 * like every other outbound call. `plan()` returns what to do; the workflow does
 * it.
 *
 * Inlined into an n8n Code node by build-workflows.js, so no backticks and no
 * dollar-brace anywhere in this file.
 */

/**
 * Which backend is live, from the environment. `env` is passed in rather than
 * read from a global so the function is testable.
 */
var backend = function (env) {
  var e = env || {};
  var forced = (e.LINKEDIN_PUBLISH_MODE || '').toLowerCase();
  if (forced === 'manual' || forced === 'publora' || forced === 'linkedin') return forced;
  // No explicit mode: infer from what is configured, most privileged first.
  if (e.LINKEDIN_API_TOKEN && e.LINKEDIN_AUTHOR_URN) return 'linkedin';
  if (e.PUBLORA_API_KEY && e.LINKEDIN_PLATFORM_ID) return 'publora';
  return 'manual';
};

/**
 * Plan the publish of one approved draft.
 *
 * `draft` is { id, final_copy, body, destination_url, hashtags }. The text sent
 * is final_copy if a human wrote one, else the drafted body: the approval step
 * writes final_copy, so anything reaching here without one was approved unchanged.
 *
 * Returns one of:
 *   { mode: 'manual',  text, destination_url, message }         copy-paste block
 *   { mode: 'publora', request: {url, method, headers, body} }  the call to make
 *   { mode: 'linkedin', request: {...} }                        the call to make
 *
 * The workflow switches on `mode`: manual writes the Teams card and marks the row
 * published-by-hand-pending; the other two make `request` and record the result.
 */
var plan = function (draft, env) {
  var d = draft || {};
  var mode = backend(env);
  var text = assemble(d);

  if (mode === 'manual') {
    return {
      mode: 'manual',
      text: text,
      destination_url: d.destination_url || null,
      message: manualMessage(text, d.destination_url),
    };
  }

  if (mode === 'publora') {
    return {
      mode: 'publora',
      request: {
        url: 'https://api.publora.com/api/v1/posts',
        method: 'POST',
        headers: {
          'Authorization': 'Bearer ' + (env.PUBLORA_API_KEY || ''),
          'Content-Type': 'application/json',
        },
        body: {
          content: text,
          platforms: [{ platform: 'linkedin', platformId: env.LINKEDIN_PLATFORM_ID }],
        },
      },
    };
  }

  // linkedin: the official /rest/posts endpoint. The author URN says whether it
  // posts as a person or as the BEXT organisation.
  return {
    mode: 'linkedin',
    request: {
      url: 'https://api.linkedin.com/rest/posts',
      method: 'POST',
      headers: {
        'Authorization': 'Bearer ' + (env.LINKEDIN_API_TOKEN || ''),
        'Content-Type': 'application/json',
        'LinkedIn-Version': env.LINKEDIN_API_VERSION || '202401',
        'X-Restli-Protocol-Version': '2.0.0',
      },
      body: {
        author: env.LINKEDIN_AUTHOR_URN,
        commentary: text,
        visibility: 'PUBLIC',
        distribution: { feedDistribution: 'MAIN_FEED', targetEntities: [], thirdPartyDistributionChannels: [] },
        lifecycleState: 'PUBLISHED',
        isReshareDisabledByAuthor: false,
      },
    },
  };
};

/**
 * The text as it will appear on LinkedIn: the body, then the hashtags on their
 * own line at the end. The link is deliberately not appended, because it belongs
 * in the first comment, not the post. `destination_url` travels alongside so the
 * human (manual) or a follow-up call (auto) can drop it there.
 */
var assemble = function (draft) {
  var d = draft || {};
  var body = String(d.final_copy || d.body || '').trim();
  var tags = (d.hashtags || []).map(function (h) {
    return String(h).replace(/^#/, '').trim();
  }).filter(Boolean).slice(0, 2);
  if (tags.length) body += '\n\n' + tags.map(function (t) { return '#' + t; }).join(' ');
  return body;
};

var manualMessage = function (text, link) {
  var lines = [];
  lines.push('Ready to publish. Paste this as a new LinkedIn post:');
  lines.push('');
  lines.push(text);
  if (link) {
    lines.push('');
    lines.push('Then, as the first comment, drop the link:');
    lines.push(link);
  }
  lines.push('');
  lines.push('When it is up, paste the post URL back into the dashboard to close the loop.');
  return lines.join('\n');
};



// --- end LinkedIn craft library ---

const all = $input.all().map(i => i.json);
const ctx = all[0] || {};
const cycle = ctx.__cycle || {};
const topic = ctx.__topic || {};
const voiceRow = ctx.__voice || {};
const recent = ctx.__recent || [];
const sources = all.filter(a => a && a.article_id).map(a => ({
  article_id: a.article_id, url: a.url, title: a.title, summary: a.summary, body: a.body,
}));

const voice = merge(voiceRow);
// Two variants: the recommended one earns comments (the reaction that compounds
// into reach), the alternative earns saves. Distinct formulas, chosen away from
// anything used recently.
const picks = pick(2, recent, voice.pillars, topic.pillar || null);
const wantGoals = ['comments', 'saves'];
const chosen = wantGoals.map((g, i) => picks[i] || picks[0]).slice(0, 2);

const sourceBlock = sources.map(s =>
  '[' + s.article_id + '] ' + (s.title || '') + '\n' + String(s.summary || s.body || '').slice(0, 800)
).join('\n\n');

const drafts = [];
for (let i = 0; i < 2; i++) {
  const variant = i === 0 ? 'A' : 'B';
  const choice = chosen[i];
  const prompt = "You are writing a single LinkedIn post for BEXT Consultancy. The selected topic, the human perspective to honour, the source material, and the voice and formula to use are all below. Write ONE post.\n\nHard requirements:\n  - The first 210 characters must stand alone as a hook, before the \"... see more\" fold.\n  - 900 to 1300 characters total. Double line breaks between ideas, not single.\n  - Every material fact must come from the source material. Do not invent a figure, a date, a rebate amount or an eligibility rule.\n  - No external link in the body. Name the destination separately.\n  - Obey the voice rules exactly, including the banned words.\n\nReturn JSON only: { \"hook\": \"...\", \"body\": \"full post text including the hook\", \"hashtags\": [\"solar\"], \"visual_concept\": \"what image runs with it\", \"cta\": \"the restrained call to action\", \"destination_url\": \"https://... or null\", \"claims\": [\"each material factual sentence, verbatim from the body\"] }."
    + '\n\n' + voicePromptBlock(voice)
    + '\n\n' + formulaPromptBlock(choice)
    + '\n\nTOPIC: ' + (topic.title || '') + '\nANGLE: ' + (topic.angle || '')
    + '\n\nHUMAN PERSPECTIVE TO HONOUR (do not contradict, build around it):\n'
    + (cycle.human_perspective || '(none supplied)')
    + '\n\nSOURCE MATERIAL:\n' + sourceBlock;

  let out;
  try { out = await geminiJSON(prompt, helpers); }
  catch (e) {
    // One variant failing must not sink the other. Record the failure as an empty
    // draft carrying the error, so the reviewer sees "B did not generate" rather
    // than a silently missing card.
    drafts.push({ variant: variant, formula: choice.formula, goal: choice.goal,
      hook: '', body: '', char_count: 0, hashtags: [], visual_concept: null, cta: null,
      destination_url: null, audit: { blockers: [{ rule: 'generation failed', detail: String(e.message || e) }], warnings: [] },
      recommended: false, claims: [] });
    continue;
  }

  // Scrub deterministically, then audit the scrubbed text. The model's own hook
  // is discarded in favour of the one computed from the final body, so the two
  // cannot disagree about what the post opens with.
  const scrubbed = scrub(String(out.body || ''));
  const body = scrubbed.text;
  const hook = hookOf(body);
  const hashtags = (out.hashtags || []).map(h => String(h).replace(/^#/, '').trim()).filter(Boolean).slice(0, 2);
  const a = audit({ body: body, hook: hook, hashtags: hashtags, destination_url: out.destination_url });
  // The scrubber's own placeholder flags join the audit warnings, so an unfilled
  // [Your Company] shows up in the same panel as everything else.
  (scrubbed.flags || []).forEach(f => a.warnings.push({ rule: f.rule, detail: f.text }));

  drafts.push({
    variant: variant, formula: choice.formula, goal: choice.goal,
    hook: hook, body: body, char_count: charCount(body), hashtags: hashtags,
    visual_concept: out.visual_concept || null, cta: out.cta || null,
    destination_url: out.destination_url || null,
    audit: { blockers: a.blockers, warnings: a.warnings, ok: a.ok },
    recommended: false,
    // The model's claim list, reconciled against the real sources. This is the
    // fact-check record: every material claim matched back or flagged.
    claims: reconcile((out.claims && out.claims.length ? out.claims : extractClaims(body)).map(c => ({ claim: c })), sources),
  });
}

// The recommended variant is the one with fewer blockers, ties broken toward the
// comments-goal draft (A). "Recommended" has to mean something, so it is the
// cleaner draft, not just the first.
const score = d => (d.audit.blockers || []).length;
if (drafts.length === 2 && score(drafts[1]) < score(drafts[0])) drafts[1].recommended = true;
else if (drafts.length) drafts[0].recommended = true;

return [{ json: { cycle_id: cycle.id, topic_id: topic.id || null,
  drafts: JSON.stringify(drafts), draft_count: drafts.length } }];
